command:
node scripts/harness.mjs bounded -- node --input-type=module -e 'import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {execFileSync} from "node:child_process";
import vm from "node:vm";
import {loadConfig} from "./scripts/lib/config.mjs";
const expected=[".angular",".nx","__screenshots__","coverage","dist","node_modules","out-tsc","playwright-report","test-output","test-results","tmp"];
const config=loadConfig(process.cwd());
const target=config.repositories["dotln-angular"];
assert.deepEqual(target.disposable,expected);
assert.equal(target.release,undefined);
assert.ok(target.authorityProfile.deniedEffects.includes("release.close"));
console.log(JSON.stringify(target.disposable));
console.log(target.release ? "declared" : "no-release");
const before=JSON.parse(execFileSync("git",["show","main:dotln.config.json"],{encoding:"utf8"}));
const after=JSON.parse(readFileSync("dotln.config.json","utf8"));
delete after.classes["angular-nx-monorepo"].disposable;
assert.deepEqual(after,before);
console.log("Configuration delta: only classes.angular-nx-monorepo.disposable added; every existing key and value preserved.");
const source=readFileSync("scripts/lib/target-worktree-close.mjs","utf8");
const match=source.match(/const underDisposable = [\s\S]*?;/);
assert.ok(match);
const underDisposable=vm.runInNewContext(match[0]+"\nunderDisposable");
for(const [path,covered] of [["dist/apps/dotln/browser/index.html",true],["dist/.playwright/apps/dotln-e2e/test-output/result.json",true],["test-output/result.json",true],["apps/example/test-output/result.json",false],["libs/example/__screenshots__/spec.png",false],[".env",false],["apps/dotln/src/environments/environment.local.ts",false]]) {
  assert.equal(underDisposable(expected,path),covered);
  console.log(`${path}: ${covered ? "covered" : "undeclared"}`);
}
'
